 public static JsonObject Validate(Snapshot state,Policy policy,string kind,JsonObject input){bool customer=kind=="customer-master";J.Require(policy.Active&&policy.Flag(customer?"manageCustomers":"createProjects"),"Master import permission required");var columns=customer?CustomerColumns:ProjectColumns;J.Require(input["headers"] is JsonArray&&input["rows"] is JsonArray,"Headers and rows required",400);var headers=input["headers"]!.AsArray().Select(x=>SpreadsheetImports.Key(x?.ToString()??"")).ToArray();J.Require(headers.Length is >0 and <=30&&headers.Distinct().Count()==headers.Length&&headers.All(h=>columns.Any(c=>SpreadsheetImports.Key(c)==h)),"Use the master template headings",400);string[] required=customer?["Customer Code","Customer Name"]:["Project Code","Project Name","Customer Code","Project Type","Project Manager","Project In-charge","Module","Primary Consultant"];foreach(var col in required)J.Require(headers.Contains(SpreadsheetImports.Key(col)),"Missing column: "+col,400);var rows=input["rows"]!.AsArray();J.Require(rows.Count is >0 and <=500,"Import 1–500 rows",400);var numbers=input["rowNumbers"] as JsonArray;if(numbers is not null)J.Require(numbers.Count==rows.Count&&numbers.All(n=>n is JsonValue v&&v.TryGetValue<int>(out var i)&&i>=2&&i<=1048576),"Invalid source rows",400);var items=new JsonArray();
 foreach(var (raw,index) in rows.Select((r,i)=>(r,i))){J.Require(raw is JsonArray&&raw.AsArray().Count<=30,"Invalid row",400);var cells=raw!.AsArray();J.Require(cells.All(c=>c is null||c is JsonValue)&&cells.All(c=>(c?.ToString().Length??0)<=6000)&&cells.Skip(headers.Length).All(c=>string.IsNullOrWhiteSpace(c?.ToString())),"Invalid or oversized cell or data beyond headings",400);string Get(string col){int i=Array.IndexOf(headers,SpreadsheetImports.Key(col));return i<0||i>=cells.Count?"":cells[i]?.ToString().Trim()??"";}var errors=new JsonArray();var warnings=new JsonArray();var values=new Dictionary<string,string>();foreach(var col in columns)values[col]=Get(col);string V(string c)=>values[c];void Error(string e)=>errors.Add(e);
