 string Day(string col){var val=V(col);if(val==""){val=J.Today.ToString("yyyy-MM-dd");warnings.Add(col+" defaulted to today");}try{J.Day(val);}catch(ApiError){Error(col+": use yyyy-mm-dd");}values[col]=val;return val;}
 JsonObject payload;
 if(customer){string code=V("Customer Code"),name=V("Customer Name"),status=V("Status")==""?"Active":V("Status");if(!Regex.IsMatch(code,"^[A-Za-z0-9_-]{1,50}$"))Error("Customer Code must be 1–50 letters, numbers, underscores or hyphens");if(name.Length is <1 or >160)Error("Customer Name must be 1–160 characters");if(!Same(status,"Active")&&!Same(status,"Inactive"))Error("Status must be Active or Inactive");if(J.A(state.Settings,"customers").Any(c=>Same(J.S(c,"code"),code)))Error("Customer code already exists; add-only import");payload=new JsonObject{["id"]=Id(),["code"]=code,["name"]=name,["active"]=!Same(status,"Inactive")};values["Status"]=Same(status,"Inactive")?"Inactive":"Active";if(J.A(state.Settings,"customers").Count()+rows.Count>5000)Error("Customer catalog limit is 5000");}
 else {string code=V("Project Code"),name=V("Project Name");if(code.Length is <1 or >50)Error("Project Code must be 1–50 characters");if(name.Length is <1 or >90)Error("Project Name must be 1–90 characters");if(state.Records.Where(k=>k.Key.StartsWith("project:")).Any(k=>Same(J.S(k.Value,"code"),code)))Error("Project code already exists; add-only import");var cust=J.A(state.Settings,"customers").Where(c=>J.B(c,"active",true)&&Same(J.S(c,"code"),V("Customer Code"))).ToList();if(cust.Count!=1)Error("Select an active Customer Code; import customers first");var types=ActivityTypes.Catalog(state.Settings).OfType<JsonObject>().Where(t=>J.B(t,"active",true)&&(Same(J.S(t,"id"),V("Project Type"))||Same(J.S(t,"name"),V("Project Type")))).ToList();string type=types.Count==1?J.S(types[0],"id"):V("Project Type");if(types.Count!=1)Error("Choose an active Project Type");values["Project Type"]=type;values["Project Manager"]=Person(V("Project Manager"),"Project Manager");values["Project In-charge"]=Person(V("Project In-charge"),"Project In-charge");values["Primary Consultant"]=Person(V("Primary Consultant"),"Primary Consultant");var extra=People(V("Additional Consultants"),"Additional Consultants");values["Additional Consultants"]=string.Join("; ",extra.Select(x=>x!.ToString()));string module=Same(V("Module"),"General")?"General":J.A(state.Settings,"moduleMaster").Where(m=>J.B(m,"active",true)&&(Same(J.S(m,"code"),V("Module"))||Same(J.S(m,"name"),V("Module")))).Select(m=>J.S(m,"name")).FirstOrDefault()??V("Module");if(module!="General"&&!J.A(state.Settings,"moduleMaster").Any(m=>J.B(m,"active",true)&&Same(J.S(m,"name"),module)))Error("Choose an active module or General");values["Module"]=module;if(V("Company")==""){values["Company"]="Company 1";warnings.Add("Company defaulted to Company 1");}if(V("Company").Length>100)Error("Company exceeds 100 characters");string start=Day("Project Start"),finish=Day("Target Finish");if(string.CompareOrdinal(finish,start)<0)Error("Target Finish cannot precede Project Start");if(V("Industry").Length>70||V("Client Contact").Length>90)Error("Industry/contact exceeds 70/90 characters");decimal budget=0;if(V("Client Mandays")!=""&&(!decimal.TryParse(V("Client Mandays"),NumberStyles.AllowDecimalPoint,CultureInfo.InvariantCulture,out budget)||budget<0||budget>1000000))Error("Client Mandays must be 0–1000000");
 payload=new JsonObject{["id"]=Id(),["code"]=code,["name"]=name,["customerId"]=cust.Count==1?J.S(cust[0],"id"):"",["stageType"]=type,["projectManager"]=V("Project Manager"),["lead"]=V("Project In-charge"),["start"]=start,["due"]=finish,["industry"]=V("Industry"),["client"]=V("Client Contact"),["clientMandays"]=budget,["health"]="On track",["modules"]=new JsonObject(),["moduleTeams"]=new JsonObject(),["companies"]=new JsonArray()};
 if(type=="amc"){string ac=V("AMC Cycle").ToLowerInvariant();ac=ac switch{"alternative days" or "alternate days"=>"alternate-days","6 months"=>"six-monthly","yearly" or "annual"=>"yearly",_=>ac};values["AMC Cycle"]=ac;string acStart=V("AMC Start"),acEnd=V("AMC End"),clock=V("AMC Preferred Start")==""?"09:00":V("AMC Preferred Start");values["AMC Preferred Start"]=clock;var roster=People(V("AMC Attendees"),"AMC Attendees");values["AMC Attendees"]=string.Join("; ",roster.Select(x=>x!.ToString()));decimal.TryParse(V("AMC Visits per Cycle"),NumberStyles.AllowDecimalPoint,CultureInfo.InvariantCulture,out var visits);decimal.TryParse(V("AMC Hours per Visit"),NumberStyles.AllowDecimalPoint,CultureInfo.InvariantCulture,out var hours);payload["amc"]=new JsonObject{["id"]=Id(),["start"]=acStart,["end"]=acEnd,["cycle"]=ac,["visits"]=visits,["hours"]=hours,["staff"]=roster,["preferredStart"]=clock,["activityId"]=""};try{Amc.Validate(state,payload,null);}catch(ApiError e){Error(e.Message);}catch(ArgumentOutOfRangeException){Error("AMC dates are outside the supported calendar range");}}
 else if(ProjectColumns.Where(c=>c.StartsWith("AMC ")).Any(c=>V(c)!=""))warnings.Add("AMC fields ignored for this project type");
 }
 var display=new JsonArray(columns.Select(c=>(JsonNode?)JsonValue.Create(values[c])).ToArray());items.Add(new JsonObject{["row"]=numbers?[index]?.DeepClone()??JsonValue.Create(index+2),["display"]=display,["errors"]=errors,["warnings"]=warnings,["payload"]=payload});
 }
 var all=items.OfType<JsonObject>().ToList();var projects=new JsonArray();
 if(customer){foreach(var item in all)if(all.Count(x=>Same(J.S(x["payload"],"code"),J.S(item["payload"],"code")))>1)item["errors"]!.AsArray().Add("Duplicate Customer Code in file");}
 else foreach(var group in all.GroupBy(i=>J.S(i["payload"],"code").ToUpperInvariant())){var list=group.ToList();var p=J.Clone(list[0]["payload"]!.AsObject());JsonObject Common(JsonObject x){var y=J.Clone(x["payload"]!.AsObject());y.Remove("id");y["code"]=J.S(y,"code").ToUpperInvariant();if(y["amc"] is JsonObject ac)ac.Remove("id");return y;}if(list.Any(x=>!JsonNode.DeepEquals(Common(x),Common(list[0]))))foreach(var item in list)item["errors"]!.AsArray().Add("Repeated project rows must have identical project/AMC fields");var pairs=new HashSet<string>();var companies=new JsonArray();var mods=new JsonObject();var teams=new JsonObject();foreach(var item in list){var display=item["display"]!.AsArray();string Val(string col)=>display[Array.IndexOf(ProjectColumns,col)]!.ToString();string companyName=Val("Company"),module=Val("Module"),primary=Val("Primary Consultant");if(!pairs.Add(companyName.ToUpperInvariant()+"|"+module.ToUpperInvariant())){foreach(var x in list)x["errors"]!.AsArray().Add("Duplicate company/module in project; use Additional Consultants for team members");continue;}var company=companies.OfType<JsonObject>().FirstOrDefault(c=>Same(J.S(c,"name"),companyName));if(company is null){company=new JsonObject{["id"]=Id(),["name"]=companyName,["modules"]=new JsonObject(),["moduleTeams"]=new JsonObject(),["goLiveStatus"]="Not ready",["plannedGoLive"]=J.S(p,"due"),["actualGoLive"]="",["moduleGoLive"]=new JsonObject()};companies.Add(company);}var people=new[]{primary}.Concat(Val("Additional Consultants").Split(';',StringSplitOptions.TrimEntries|StringSplitOptions.RemoveEmptyEntries)).Distinct().ToArray();company["modules"]![module]=primary;company["moduleTeams"]![module]=new JsonArray(people.Select(x=>(JsonNode?)JsonValue.Create(x)).ToArray());if(!mods.ContainsKey(module))mods[module]=primary;if(teams[module] is not JsonArray)teams[module]=new JsonArray();foreach(var person in people)if(!teams[module]!.AsArray().Any(x=>x?.ToString()==person))teams[module]!.AsArray().Add(person);}
 p["modules"]=mods;p["moduleTeams"]=teams;p["companies"]=companies;p["masterImportedBy"]=policy.Actor;p["masterImportedAt"]=DateTimeOffset.UtcNow.ToString("O");if(list.All(x=>x["errors"]!.AsArray().Count==0))try{J.Require(p.ToJsonString().Length<=500000,"Project record too large",400);ActivityTypes.Project(state.Settings,p,null);Workforce.Project(state,p,null);Amc.Validate(state,p,null);ProjectOwnership.Validate(state,p,null);Psr.Validate(p,null);ProjectCompanies.Validate(p,null);}catch(ApiError e){foreach(var item in list)item["errors"]!.AsArray().Add(e.Message);}projects.Add(p);
 }
 return new JsonObject{["kind"]=kind,["revision"]=state.Revision,["columns"]=new JsonArray(columns.Select(c=>(JsonNode?)JsonValue.Create(c)).ToArray()),["items"]=items,["projects"]=projects,["validCount"]=all.Count(i=>i["errors"]!.AsArray().Count==0),["invalidCount"]=all.Count(i=>i["errors"]!.AsArray().Count>0),["recordCount"]=customer?all.Count:projects.Count};
 }
 public static JsonObject Apply(Snapshot state,Policy policy,string kind,JsonObject input){var preview=Validate(state,policy,kind,input);J.Require(J.N(preview,"invalidCount")==0,"Master import contains row errors; revalidate first",400);if(kind=="customer-master"){var catalog=new JsonArray(J.A(state.Settings,"customers").Select(c=>(JsonNode)J.Clone(c)).Concat(J.A(preview,"items").Select(i=>(JsonNode)J.Clone(i["payload"]!.AsObject()))).ToArray());policy.UpdateCustomers(catalog);}else policy.Apply(new JsonObject{["records"]=new JsonArray(J.A(preview,"projects").Select(p=>(JsonNode)new JsonObject{["kind"]="project",["id"]=J.S(p,"id"),["payload"]=p.DeepClone()}).ToArray())});return new JsonObject{["count"]=J.N(preview,"validCount"),["recordCount"]=J.N(preview,"recordCount"),["kind"]=kind};}
